#!/usr/bin/env python3
"""Write src/algo_carriers.h: for each algorithm a bitmask of its carriers (operators that reach the output; bit n-1 = operator n).
They are the boxes on the bottom row of gen_algo_svgs.ALGOS (row 3). Used by GENERATE."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from gen_algo_svgs import ALGOS
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
masks = [sum(1 << (op - 1) for op, col, row, l, f in ops if row == 3) for ops in ALGOS]
open(os.path.join(ROOT, "src", "algo_carriers.h"), "w").write(
    "/* generated by tools/gen_algo_carriers.py: do not edit */\n#pragma once\nstatic const unsigned char kAlgoCarriers[32] = {" + ",".join(str(m) for m in masks) + "};\n")
print([[o + 1 for o in range(6) if m >> o & 1] for m in masks])
